begin
  perform erp.require_owner_admin();
  return query
  select 'MATERIAL_RECOST_GL_STATE_DRIFT','ERROR',count(*)::bigint,'Material movement recost target differs from applied automatic GL revaluation'
  from (
    select msm.id
    from erp.material_stock_movements msm
    left join erp.material_cost_revaluation_state s on s.movement_id=msm.id
    where msm.movement_type<>'REVERSAL'
      and msm.source_type in('CUTTING_GROUP','CUTTING_GROUP_RETURN','CONTRACTOR_MATERIAL_ISSUE_ITEM','MATERIAL_ADJUSTMENT_ITEM','MATERIAL_SUPPLIER_RETURN_ITEM')
      and abs((case when exists(select 1 from erp.material_stock_movements rv where rv.reversal_of_id=msm.id) then 0
                    else round(msm.qty_signed*(msm.unit_cost_snapshot-coalesce(msm.original_unit_cost_snapshot,msm.unit_cost_snapshot)),2) end)
              -coalesce(s.applied_inventory_delta,0))>0.01
  ) x;

  return query
  select 'MATERIAL_GL_VALUATION_MISMATCH','ERROR',
    case when abs(v.ledger_value-v.gl_value)>0.05 then 1 else 0 end::bigint,
    'Material moving-average ledger value differs from Material Inventory GL by more than 0.05'
  from (
    select
      coalesce((select sum(coalesce(m.cached_stock_qty,0)*coalesce(m.moving_average_cost,0)) from erp.materials m),0)::numeric as ledger_value,
      coalesce((select sum(adb.debit_total-adb.credit_total) from erp.account_daily_balances adb where adb.account_id=erp.account_id('MATERIAL_INVENTORY')),0)::numeric as gl_value
  ) v;
